/* animated-qr-generate.js — makes tests/fixtures/animated-qr.json with the
 * library cashu.me uses to draw animated QR codes, so Foxy's reader
 * (Foxy/Scanner/AnimatedQR.swift) is tested against the real encoder.
 *
 * Not run by any check: the fixture is committed. To make it again, in an empty
 * folder, with the versions cashu.me's package-lock.json pins (checked
 * at cashubtc/cashu.me 4abd2683):
 *
 *   npm install @gandlaf21/bc-ur@1.1.12 cborg@4.2.0 bignumber.js@9.1.2 \
 *     @noble/hashes@1.5.0 jsbi@3.1.5 @apocentre/alias-sampling@0.5.3 buffer esbuild@0.25.0
 *   cp <Foxy>/tests/fixtures/animated-qr-generate.js gen.js
 *   npx esbuild gen.js --bundle --platform=node --main-fields=module,main --outfile=gen.bundle.js
 *   FOXY=<Foxy> node gen.bundle.js
 *
 * esbuild takes the library's ES module build, as cashu.me's bundler does; its
 * CommonJS build cannot load cborg 4. */
const { UR, UREncoder } = require('@gandlaf21/bc-ur');
const { chooseFragments } = require('@gandlaf21/bc-ur/dist/lib/es6/fountainUtils.js');
const { getCRC } = require('@gandlaf21/bc-ur/dist/lib/es6/utils.js');
const fs = require('fs'), crypto = require('crypto');
// deterministic filler: a token-shaped string of a given length
function tokenOf(n, seed) {
  const abc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  let out = 'cashuB', h = crypto.createHash('sha256').update(String(seed)).digest();
  while (out.length < n) { h = crypto.createHash('sha256').update(h).digest(); for (const b of h) { if (out.length >= n) break; out += abc[b & 63]; } }
  return out;
}
const real = fs.readFileSync((process.env.FOXY || '..') + '/tests/vectors/' + fs.readdirSync((process.env.FOXY || '..') + '/tests/vectors').find(f => /nut-?00/i.test(f)), 'utf8').match(/cashuB[A-Za-z0-9_\-=+/]{40,}/g) || [];
const cases = [];
const tokens = [
  ['a short token: one frame', tokenOf(40, 1), 150],
  ['a spec token', real[0] || tokenOf(300, 2), 50],
  ['600 characters, cashu.me\'s short frames', tokenOf(600, 3), 50],
  ['600 characters, medium frames', tokenOf(600, 4), 100],
  ['3,000 characters, long frames', tokenOf(3000, 5), 150],
  ['12,000 characters, medium frames', tokenOf(12000, 6), 100],
];
for (const [name, token, len] of tokens) {
  const enc = new UREncoder(UR.fromBuffer(Buffer.from(token)), len, 0);
  const n = enc.fragmentsLength;
  const frames = [];
  for (let i = 0; i < Math.max(1, n * 3); i++) frames.push(enc.nextPart());
  cases.push({ name, token, fragmentLength: len, seqLength: n, frames });
}
const choose = [];
for (const seqLen of [2, 3, 10, 57, 200, 900]) for (const checksum of [0, 1, 0xdeadbeef, 3217482356]) {
  for (let seqNum = seqLen + 1; seqNum <= seqLen + 12; seqNum++) choose.push({ seqNum, seqLen, checksum, indexes: chooseFragments(seqNum, seqLen, checksum) });
}
choose.push({ seqNum: 4294967295, seqLen: 17, checksum: 12345, indexes: chooseFragments(4294967295, 17, 12345) });
const crc = [['', getCRC(Buffer.from(''))], ['Hello, world!', getCRC(Buffer.from('Hello, world!'))]];
fs.writeFileSync((process.env.FOXY || '..') + '/tests/fixtures/animated-qr.json', JSON.stringify({ source: '@gandlaf21/bc-ur 1.1.12 (cashu.me), generated by tests/fixtures/animated-qr-generate.js', cases, chooseFragments: choose, crc32: crc }, null, 1));
console.log(cases.map(c => c.name + ': ' + c.seqLength + ' fragments, ' + c.frames.length + ' frames, first ' + c.frames[0].slice(0, 40)).join('\n'));
console.log('size', fs.statSync((process.env.FOXY || '..') + '/tests/fixtures/animated-qr.json').size);
